package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.core.*;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.*;import net.minecraft.world.item.context.*;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.phys.*;import net.minecraft.network.chat.Component;import java.util.*;
public final class Pb01Item extends BlockItem{
 public Pb01Item(Block b,Properties p){super(b,p);}public static Direction face(Player p,ItemStack s){var f=p==null?Direction.NORTH:p.getDirection().getOpposite();for(int i=0;i<(DefenseItem.data(s).getInt("PbRotation")&3);i++)f=f.getClockWise();return f;}public static BlockPos anchor(BlockPos above,Direction f){return above.relative(f.getOpposite(),6);}
 @Override public InteractionResult useOn(UseOnContext c){if(c.getPlayer()!=null&&c.getPlayer().isShiftKeyDown()){var n=DefenseItem.data(c.getItemInHand());n.putInt("PbRotation",(n.getInt("PbRotation")+1)&3);DefenseItem.data(c.getItemInHand(),n);return InteractionResult.SUCCESS;}return super.useOn(c);}
 @Override public BlockPlaceContext updatePlacementContext(BlockPlaceContext c){if(c.getClickedFace()!=Direction.UP)return null;var p=anchor(c.getClickedPos(),face(c.getPlayer(),c.getItemInHand()));return BunkerVegetation.at(c,p);}
 public static String check(Level l,BlockPos root,Direction face,Player p,ItemStack item){var b=Pb01Geometry.MODEL.bounds(root,face);if(b.minY<l.getMinBuildHeight()||b.maxY>l.getMaxBuildHeight())return "HEIGHT";for(var at:BlockPos.betweenClosed(BlockPos.containing(b.minX,b.minY,b.minZ),BlockPos.containing(b.maxX-1e-6,b.maxY-1e-6,b.maxZ-1e-6))){if(!l.hasChunkAt(at))return "UNLOADED";if(!l.getWorldBorder().isWithinBounds(at)||p!=null&&(!l.mayInteract(p,at)||!p.mayUseItemAt(at,Direction.UP,item)))return "DENIED";if(!BunkerVegetation.replaceable(l,at))return "BLOCKED";}for(var c:Pb01Geometry.MODEL.support){var at=Pb01Geometry.cell(root,face,c).below();if(!l.hasChunkAt(at)||!l.getBlockState(at).isFaceSturdy(l,at,Direction.UP))return "FOUNDATION";}if(!l.getEntities((net.minecraft.world.entity.Entity)null,b,e->!e.isSpectator()&&!e.isRemoved()&&!(e instanceof net.minecraft.world.entity.ExperienceOrb)).isEmpty())return "OCCUPIED";if((Pb01BlockEntity.broken(DefenseItem.data(item).getCompound("BunkerState"))&1)!=0)return "DESTROYED";return "";}
 @Override protected boolean canPlace(BlockPlaceContext c,BlockState s){var why=check(c.getLevel(),c.getClickedPos(),s.getValue(Pb01Block.FACING),c.getPlayer(),c.getItemInHand());if(!why.isEmpty()&&c.getPlayer()!=null)c.getPlayer().displayClientMessage(Component.translatable("defense.status."+why),true);return why.isEmpty()&&super.canPlace(c,s);}
 @Override protected boolean placeBlock(BlockPlaceContext c,BlockState s){int broken=Pb01BlockEntity.broken(DefenseItem.data(c.getItemInHand()).getCompound("BunkerState"));boolean lights=!DefenseItem.data(c.getItemInHand()).getCompound("BunkerState").contains("Lights")||DefenseItem.data(c.getItemInHand()).getCompound("BunkerState").getBoolean("Lights");var tx=new BunkerVegetation.Transaction(c.getLevel());boolean old=Pb01Block.MUTATING.get();Pb01Block.MUTATING.set(true);try{var g=Pb01Geometry.MODEL;if(!tx.clear(g.bounds(c.getClickedPos(),s.getValue(Pb01Block.FACING))))return false;for(int k=0;k<2;k++){boolean moving=k==1;var cs=moving?g.door:g.body;var bases=moving?g.doorBase:g.bodyBase;for(int i=0;i<cs.length;i++){int v=g.variant(moving,bases[i],broken);if(g.variant(moving,v).mask()==0)continue;var at=Pb01Geometry.cell(c.getClickedPos(),s.getValue(Pb01Block.FACING),cs[i]);var next=moving?Pb01Block.part(AddonBlocks.PB01_DOOR.get().defaultBlockState().setValue(Pb01Block.FACING,s.getValue(Pb01Block.FACING)),v):Pb01Block.part(s,v).setValue(Pb01Block.LIT,lights&&g.lamp(cs[i]));if(!tx.set(at,next)){tx.rollback();return false;}}}return true;}finally{Pb01Block.MUTATING.set(old);}}
 @Override public void appendHoverText(ItemStack s,Level c,List<Component>text,TooltipFlag f){text.add(Component.translatable("pb01.description"));text.add(Component.translatable("pb01.controls"));}
 @Override public void initializeClient(java.util.function.Consumer<net.minecraftforge.client.extensions.common.IClientItemExtensions>c){c.accept(new net.minecraftforge.client.extensions.common.IClientItemExtensions(){@Override public net.minecraft.client.renderer.BlockEntityWithoutLevelRenderer getCustomRenderer(){return Pb01ItemRenderer.instance();}});}
}
